'use strict';
const {SERVICES,STATES,shift,size,minutes,money,range,createStore}=CRM;
const store=createStore();
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={paw:'<path d="M8 14c-3 2-5 5-3 7s5 0 7 0 5 2 7 0 0-5-3-7c-2-3-6-3-8 0Z"/><ellipse cx="5" cy="9" rx="2" ry="3"/><ellipse cx="10" cy="5" rx="2" ry="3"/><ellipse cx="16" cy="5" rx="2" ry="3"/><ellipse cx="21" cy="10" rx="2" ry="3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',wallet:'<path d="M20 8V5H6a3 3 0 0 0 0 6h15v10H6a3 3 0 0 1-3-3V8m18 6h-6v4h6"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-.8L3 21l1.8-5A9 9 0 1 1 21 11Z"/><path d="M8 9h8m-8 5h5"/>',tag:'<path d="M20 13 11 22 2 13V2h11l9 9Z"/><circle cx="7" cy="7" r="1"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',chevron:'<path d="m9 5 7 7-7 7"/>',scissors:'<circle cx="5" cy="6" r="3"/><circle cx="5" cy="18" r="3"/><path d="m7 8 14 13M7 16 21 3"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.paw}</svg>`;
const state=()=>store.get();
const pet=id=>state().pets.find(p=>p.id===id);
const owner=id=>state().owners.find(c=>c.id===id);
const paid=id=>state().payments.some(p=>p.appointmentId===id);
const initials=name=>name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=p=>`<span class="pet-avatar color-${p.color}">${esc(p.name.slice(0,1))}</span>`;
const dateLabel=(date,short=false)=>date?new Intl.DateTimeFormat('es-ES',short?{day:'numeric',month:'short'}:{weekday:'long',day:'numeric',month:'long'}).format(new Date(date+'T12:00:00')):'Primera visita';
const badge=status=>`<span class="badge ${status}"><span></span>${STATES[status]}</span>`;
const routes=[['resumen','Resumen','grid'],['agenda','Agenda','calendar'],['clientes','Clientes y mascotas','users'],['caja','Caja','wallet'],['seguimiento','Seguimiento','chat'],['tarifas','Servicios y tarifas','tag']];
let viewDate=state().today,query='',statusFilter='',modalType='',timer;
const followups=()=>state().pets.filter(p=>p.nextVisit<=shift(state().today,7));
const route=()=>routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'resumen';
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,4000);}
function fillIcons(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon');});}
function heading(title,subtitle,button='Nueva cita',action='new-appointment'){return `<div class="page-heading"><div><p class="eyebrow">${esc(dateLabel(state().today))}</p><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div>${button?`<button class="button primary" data-action="${action}">${icon('plus')}${button}</button>`:''}</div>`;}
function appointmentActions(a){let html='';if(a.status==='pending')html=`<button class="mini-button" data-action="confirm" data-id="${a.id}">Confirmar</button>`;if(a.status==='confirmed')html=`<button class="mini-button" data-action="start" data-id="${a.id}">Empezar</button>`;if(a.status==='active')html=`<button class="mini-button dark" data-action="finish" data-id="${a.id}">Finalizar</button>`;if(a.status==='done')html=paid(a.id)?`<span class="paid-label">${icon('check')}Cobrado</span>`:`<button class="mini-button dark" data-action="payment" data-id="${a.id}">Cobrar</button>`;if(['pending','confirmed'].includes(a.status))html+=`<button class="icon-button cancel-button" data-action="cancel" data-id="${a.id}" aria-label="Cancelar cita de ${esc(pet(a.petId).name)}" title="Cancelar cita">${icon('close')}</button>`;return html||'<span class="muted">—</span>';}
function appointmentTable(list){return list.length?`<div class="table-scroll"><table class="appointment-table"><thead><tr><th>Hora</th><th>Mascota / cliente</th><th>Servicio</th><th>Estado</th><th>Importe</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody>${list.map(a=>{const p=pet(a.petId),c=owner(p.ownerId);return `<tr class="${a.status==='active'?'active-row':''}"><td class="time-cell"><strong>${a.time}</strong><small>${a.duration} min</small></td><td><button class="pet-link" data-action="pet" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(c.name)}</small></span></button></td><td><span class="service-name">${SERVICES[a.service].name}</span><small class="channel">${a.channel}</small></td><td>${badge(a.status)}</td><td class="amount">${money(a.amount)}</td><td><div class="row-actions">${appointmentActions(a)}</div></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty">${icon('calendar')}<h3>No hay citas en esta vista</h3><p>Prueba otra fecha o añade una cita de demostración.</p><button class="button secondary" data-action="new-appointment">Crear una cita</button></div>`;}
function sortedAppointments(date){return state().appointments.filter(a=>a.date===date).sort((a,b)=>a.time.localeCompare(b.time));}
function kpis(date=state().today){const items=state().appointments.filter(a=>a.date===date&&a.status!=='cancelled'),payments=state().payments.filter(p=>p.date===date);return `<div class="kpi-grid">${[[items.length,'Citas del día','calendar',`${items.filter(a=>a.status==='done').length} servicios finalizados`], [items.filter(a=>a.status==='pending').length,'Por confirmar','clock','Consultas listas para gestionar'],[money(payments.reduce((s,p)=>s+p.amount,0)),'Cobrado hoy','wallet','Registro simulado de cobros'],[followups().filter(p=>!state().followed.includes(p.id)).length,'Próximas revisitas','paw','Pendientes de preparar']].map(([n,label,i,note],index)=>`<article class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon kpi-${index}">${icon(i)}</span></div><strong>${n}</strong><p>${note}</p></article>`).join('')}</div>`;}
function renderSummary(){const active=state().appointments.find(a=>a.date===state().today&&a.status==='active');const next=state().appointments.find(a=>a.date===state().today&&a.status==='confirmed');const feature=active||next;return heading('Tu día, de un vistazo.','Menos tiempo organizando. Más tiempo cuidando de ellos.')+kpis()+`<div class="overview-grid"><section class="panel agenda-panel"><div class="panel-heading"><div><h2>La agenda de hoy</h2><p>${esc(dateLabel(state().today))} · Un puesto de trabajo</p></div><a href="#agenda" class="text-link">Ver agenda</a></div>${appointmentTable(sortedAppointments(state().today).filter(a=>a.status!=='cancelled'))}</section><div class="right-stack">${feature?`<section class="spotlight"><div class="spotlight-label">${icon('scissors')}${active?'EN SERVICIO':'PRÓXIMA VISITA'}</div><div class="spotlight-pet">${avatar(pet(feature.petId))}<div><h2>${esc(pet(feature.petId).name)}</h2><p>${esc(pet(feature.petId).breed)} · ${pet(feature.petId).weight} kg</p></div></div><p class="spotlight-service">${SERVICES[feature.service].name}</p><div class="spotlight-time">${icon('clock')}${feature.time} · ${feature.duration} min de ejemplo</div><div class="care-note"><strong>Un detalle que importa</strong><p>${esc(pet(feature.petId).notes)}</p></div><button class="button dark" data-action="${active?'finish':'pet'}" data-id="${active?feature.id:feature.petId}">${active?'Finalizar servicio':'Abrir ficha'}</button></section>`:''}<section class="panel followup-panel"><div class="panel-heading"><h2>Volver a verles</h2><span class="count-pill">${followups().length}</span></div><p class="muted followup-intro">Una atención que continúa después de la visita.</p>${followups().slice(0,3).map(p=>`<button class="followup-mini" data-action="message" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${state().followed.includes(p.id)?'Mensaje preparado':p.nextVisit<state().today?'Revisita pendiente':dateLabel(p.nextVisit,true)}</small></span>${icon('chevron')}</button>`).join('')}<a href="#seguimiento" class="text-link followup-link">Ver seguimiento</a></section></div></div>`;}
function renderAgenda(){let list=sortedAppointments(viewDate);if(statusFilter)list=list.filter(a=>a.status===statusFilter);return heading('Cada cita, en su sitio.','De la primera consulta al último mimo.')+`<section class="panel"><div class="agenda-toolbar"><div class="date-controls"><button class="icon-button prev" data-action="previous-day" aria-label="Día anterior">${icon('chevron')}</button><label class="sr-only" for="agenda-date">Fecha de la agenda</label><input type="date" id="agenda-date" value="${viewDate}"><button class="icon-button" data-action="next-day" aria-label="Día siguiente">${icon('chevron')}</button><button class="mini-button" data-action="today">Hoy</button></div><div class="agenda-filters"><span>Un puesto · Horario de ejemplo</span><label class="sr-only" for="status-filter">Filtrar por estado</label><select id="status-filter"><option value="">Todos los estados</option>${Object.entries(STATES).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="agenda-date-title"><h2>${esc(dateLabel(viewDate))}</h2><span>${list.length} citas en esta vista</span></div>${appointmentTable(list)}</section><p class="view-footnote">La demo detecta solapamientos para un puesto. Las duraciones y el horario son de ejemplo.</p>`;}
function renderClients(){const q=query.toLocaleLowerCase('es');const list=state().pets.filter(p=>[p.name,p.breed,owner(p.ownerId).name].some(t=>t.toLocaleLowerCase('es').includes(q)));return heading('Conocerles cambia el cuidado.','Sus preferencias, su familia y cada visita, en una sola ficha.','Nueva ficha','new-pet')+`<section class="panel"><div class="clients-toolbar"><label class="search-box">${icon('search')}<input id="pet-search" type="search" placeholder="Buscar mascota, cliente o raza" value="${esc(query)}" aria-label="Buscar mascota, cliente o raza"></label><span class="muted">${state().owners.length} clientes · ${state().pets.length} mascotas</span></div><div class="pet-grid">${list.map(p=>`<article class="pet-card"><div class="pet-card-heading">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>${esc(p.breed)} · ${p.weight} kg</p></div></div><dl><div><dt>Su familia</dt><dd>${esc(owner(p.ownerId).name)}</dd></div><div><dt>Última visita</dt><dd>${dateLabel(p.lastVisit,true)}</dd></div></dl><p class="pet-note">${esc(p.notes||'Añade sus preferencias en la ficha.')}</p><div class="pet-card-actions"><button class="mini-button" data-action="pet" data-id="${p.id}">Ver ficha</button><button class="text-link" data-action="new-appointment" data-id="${p.id}">Nueva cita</button></div></article>`).join('')||'<div class="empty"><h3>No encontramos coincidencias</h3><p>Prueba con otro nombre, cliente o raza.</p></div>'}</div></section>`;}
function renderCash(){const payments=state().payments.filter(p=>p.date===state().today),due=state().appointments.filter(a=>a.status==='done'&&!paid(a.id));return heading('Las cuentas, claras.','Registro de cobros de demostración. No procesa pagos ni emite facturas.','','')+`<div class="cash-metrics">${['Tarjeta','Efectivo','Bizum'].map(m=>`<article class="kpi"><div class="kpi-top"><span>${m}</span>${icon('wallet')}</div><strong>${money(payments.filter(p=>p.method===m).reduce((s,p)=>s+p.amount,0))}</strong><p>Cobros simulados de hoy</p></article>`).join('')}</div><section class="panel due-panel"><div class="panel-heading"><div><h2>Pendientes de cobro</h2><p>Solo servicios finalizados</p></div><span class="count-pill">${due.length}</span></div>${due.length?appointmentTable(due):'<div class="inline-empty">Todo al día. No hay servicios finalizados pendientes de cobro.</div>'}</section><section class="panel"><div class="panel-heading"><h2>Movimientos de hoy</h2><strong>${money(payments.reduce((s,p)=>s+p.amount,0))}</strong></div><div class="table-scroll"><table><thead><tr><th>Mascota</th><th>Servicio</th><th>Método</th><th>Importe</th><th>Registro</th></tr></thead><tbody>${payments.map(p=>{const a=state().appointments.find(x=>x.id===p.appointmentId);return `<tr><td><button class="pet-link" data-action="pet" data-id="${a.petId}">${avatar(pet(a.petId))}<strong>${esc(pet(a.petId).name)}</strong></button></td><td>${SERVICES[a.service].name}</td><td>${p.method}</td><td class="amount">${money(p.amount)}</td><td><span class="simulation-tag">Simulado</span></td></tr>`;}).join('')||'<tr><td colspan="5">Aún no hay cobros de ejemplo.</td></tr>'}</tbody></table></div></section>`;}
function renderFollowup(){return heading('Que la próxima visita no se pierda.','Prepara una atención cercana para quienes vuelven a confiar en vosotros.','','')+`<div class="followup-notice">${icon('info')}<p>Fechas de ejemplo, no recomendaciones de cuidado. Los mensajes se pueden copiar, pero la demo no los envía.</p></div><section class="panel"><div class="panel-heading"><div><h2>Revisitas próximas y pendientes</h2><p>Hasta ${dateLabel(shift(state().today,7),true)}</p></div><span class="count-pill">${followups().length}</span></div><div class="table-scroll"><table><thead><tr><th>Mascota</th><th>Cliente</th><th>Revisita prevista</th><th>Preparación</th><th>Acciones</th></tr></thead><tbody>${followups().map(p=>`<tr><td><button class="pet-link" data-action="pet" data-id="${p.id}">${avatar(p)}<strong>${esc(p.name)}</strong></button></td><td>${esc(owner(p.ownerId).name)}</td><td>${dateLabel(p.nextVisit,true)}${p.nextVisit<state().today?'<small class="overdue">Pendiente</small>':''}</td><td><span class="badge ${state().followed.includes(p.id)?'confirmed':'pending'}">${state().followed.includes(p.id)?'Preparado':'Por preparar'}</span></td><td><button class="mini-button" data-action="message" data-id="${p.id}">Ver mensaje</button></td></tr>`).join('')||'<tr><td colspan="5">No quedan revisitas para esta semana.</td></tr>'}</tbody></table></div></section>`;}
function renderRates(){return heading('Vuestros servicios. Vuestras tarifas.','Precios publicados en laperruqueria.es, incorporados a la propuesta.','','')+`<div class="rates-grid">${Object.entries(SERVICES).map(([key,s])=>`<section class="panel rate-card"><span class="rate-icon">${icon(key==='cut'?'scissors':key==='bath'?'paw':'tag')}</span><h2>${s.name}</h2><p>${key==='bath'?'Incluye uñas, oídos y plantares':key==='shed'?'Según cantidad de subpelo':'Arreglo completo profesional'}</p><dl>${[['small','Pequeño','Hasta 10 kg'],['medium','Mediano','10–25 kg'],['large','Grande','Más de 25 kg']].map(([b,n,w])=>`<div><dt>${n}<small>${w}</small></dt><dd>${s.prices[b][0]}–${s.prices[b][1]} €${s.openLarge&&b==='large'?'+':''}</dd></div>`).join('')}</dl><span class="duration-note">Agenda demo: ${s.duration} min por sesión</span></section>`).join('')}</div><div class="rates-source">${icon('info')}<p>Tarifas consultadas el 3 de octubre de 2026 en <a href="https://laperruqueria.es/" target="_blank" rel="noopener noreferrer">la web de La Perruquería</a>. Las duraciones, el puesto de trabajo y los importes concretos de las citas son supuestos de demostración. El precio final se confirma con el negocio.</p></div>`;}
function render(){const r=route();$('crumb').textContent=routes.find(x=>x[0]===r)[1];$('navigation').innerHTML=routes.map(([id,label,i])=>`<a href="#${id}" aria-label="${label}" ${id===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='seguimiento'?`<b>${followups().filter(p=>!state().followed.includes(p.id)).length}</b>`:''}</a>`).join('');$('main').innerHTML=({resumen:renderSummary,agenda:renderAgenda,clientes:renderClients,caja:renderCash,seguimiento:renderFollowup,tarifas:renderRates})[r]();fillIcons();}
function modal(title,body,type=''){modalType=type;$('modal-title').textContent=title;$('modal-body').innerHTML=body;fillIcons();if(!$('modal').open)$('modal').showModal();}
const errorBox='<p id="form-error" class="form-error" role="alert" hidden></p>';
function petModal(id){const p=pet(id),c=owner(p.ownerId);modal(`La ficha de ${p.name}`,`<div class="profile-top">${avatar(p)}<div><strong>${esc(p.breed)} · ${p.weight} kg</strong><p>${esc(c.name)} · ${esc(c.phone)}</p></div></div><form id="notes-form" data-id="${p.id}"><label for="pet-notes">Preferencias y cuidados</label><textarea id="pet-notes" maxlength="1000" rows="3">${esc(p.notes)}</textarea><div class="form-actions small-actions"><button class="button secondary" type="submit">Guardar notas</button><button type="button" class="button primary" data-action="new-appointment" data-id="${p.id}">Nueva cita</button></div></form><h3 class="section-title">Historial de visitas</h3><div class="history-list">${p.history.map(h=>`<article><span class="history-dot"></span><div><strong>${SERVICES[h.service].name}</strong><p>${esc(h.note)}</p><small>${dateLabel(h.date,true)} · ${money(h.amount)}</small></div></article>`).join('')||'<p class="muted">Sin visitas previas. Su historia empieza aquí.</p>'}</div><p class="modal-footnote">Ficha ficticia. Los cambios se guardan solo durante esta sesión.</p>`,'pet');}
function appointmentModal(petId){const chosen=pet(petId)||state().pets[0];modal('Una nueva visita',`<form id="appointment-form"><p class="form-intro">Registra una consulta recibida por WhatsApp, Instagram, teléfono o en tienda.</p><div class="form-grid"><div class="full"><label for="appointment-pet">Mascota y cliente</label><select id="appointment-pet" required>${state().pets.map(p=>`<option value="${p.id}" ${p.id===chosen.id?'selected':''}>${esc(p.name)} · ${esc(owner(p.ownerId).name)} · ${p.weight} kg</option>`).join('')}</select></div><div class="full"><label for="appointment-service">Servicio</label><select id="appointment-service">${Object.entries(SERVICES).map(([k,s])=>`<option value="${k}">${s.name}</option>`).join('')}</select></div><div><label for="appointment-date">Fecha</label><input id="appointment-date" type="date" min="${state().today}" value="${viewDate<state().today?state().today:viewDate}" required></div><div><label for="appointment-time">Hora</label><input id="appointment-time" type="time" min="09:00" max="19:15" value="09:00" required></div><div><label for="appointment-amount">Importe demo (€)</label><input id="appointment-amount" type="number" min="0.01" max="1000" step="0.01" required></div><div><label for="appointment-channel">Origen de la consulta</label><select id="appointment-channel"><option>WhatsApp</option><option>Instagram</option><option>Teléfono</option><option>En tienda</option></select></div></div><div id="appointment-estimate" class="estimate-box"></div>${errorBox}<div class="form-actions"><button class="button secondary" type="button" data-action="close-modal">Cancelar</button><button class="button primary" type="submit">Crear cita demo</button></div><p class="modal-footnote">Horario simulado: 09:00–20:00 · Un puesto. No se envía ninguna confirmación real.</p></form>`,'appointment');updateEstimate();}
function updateEstimate(){const p=pet($('appointment-pet').value),s=$('appointment-service').value;const band=SERVICES[s].prices[size(p.weight)];$('appointment-amount').value=Math.round((band[0]+band[1])/2);$('appointment-estimate').innerHTML=`${icon('tag')}<span>Tarifa publicada: <strong>${range(s,p.weight)}</strong><small>Duración de ejemplo: ${SERVICES[s].duration} min. Puedes ajustar el importe simulado.</small></span>`;}
function newPetModal(){modal('Conocer a un nuevo peludo',`<form id="new-pet-form"><p class="form-intro">Prueba una ficha con datos inventados. No hace falta ningún contacto real.</p><div class="form-grid"><div><label for="new-pet-name">Nombre de la mascota</label><input id="new-pet-name" required maxlength="60" placeholder="Ej. Bimba"></div><div><label for="new-owner">Nombre del cliente</label><input id="new-owner" required maxlength="90" placeholder="Ej. Ana Demo"></div><div><label for="new-breed">Raza o descripción</label><input id="new-breed" required maxlength="80" placeholder="Ej. Mestiza"></div><div><label for="new-weight">Peso (kg)</label><input id="new-weight" type="number" min="0.1" max="120" step="0.1" required placeholder="8"></div><div class="full"><label for="new-notes">Preferencias</label><textarea id="new-notes" rows="3" maxlength="1000" placeholder="¿Qué conviene recordar en su próxima visita?"></textarea></div></div>${errorBox}<div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button type="submit" class="button primary">Crear ficha demo</button></div></form>`,'new-pet');}
function paymentModal(id){const a=state().appointments.find(x=>x.id===id);modal('Registrar un cobro de prueba',`<form id="payment-form" data-id="${id}"><div class="payment-summary"><span>${esc(pet(a.petId).name)} · ${SERVICES[a.service].name}</span><strong>${money(a.amount)}</strong></div><label for="payment-method">Método de pago</label><select id="payment-method"><option>Tarjeta</option><option>Efectivo</option><option>Bizum</option></select><p class="form-intro">Este registro es ficticio. No se carga dinero, no se conecta con un banco y no se emite factura.</p>${errorBox}<div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button type="submit" class="button primary">Registrar cobro simulado</button></div></form>`,'payment');}
function messageModal(id){const p=pet(id);const message=`¡Hola, ${owner(p.ownerId).name.split(' ')[0]}! Somos La Perruquería 🐾. ¿Cómo está ${p.name}? Si os viene bien una próxima visita, podemos buscar un hueco para sus cuidados. ¡Nos encantará volver a verle!`;modal(`Un mensaje para la familia de ${p.name}`,`<p class="form-intro">Texto de ejemplo para una revisita. Revísalo antes de usarlo con clientes reales.</p><label for="followup-message">Borrador editable</label><textarea id="followup-message" rows="6" maxlength="1500">${esc(message)}</textarea><div class="form-actions"><button class="button secondary" data-action="copy-message">${icon('copy')}Copiar texto</button><button class="button primary" data-action="mark-prepared" data-id="${id}">Marcar preparado</button></div><p class="modal-footnote">No se envía ningún mensaje. El contacto mostrado es ficticio.</p>`,'message');}
function guide(){modal('Una demo para enseñar en 3 minutos',`<div class="guide-steps"><article><b>1</b><div><h3>Del mensaje a la agenda</h3><p>Abre «Nueva cita», escoge una mascota y registra una consulta. Prueba mañana a las 10:00.</p></div></article><article><b>2</b><div><h3>Un cuidado que recuerda</h3><p>Abre una ficha, consulta el historial y guarda una preferencia para la próxima visita.</p></div></article><article><b>3</b><div><h3>Del servicio al cobro</h3><p>Finaliza el servicio de Nala y registra un cobro simulado. Verás la caja y el historial actualizarse.</p></div></article><article><b>4</b><div><h3>Una próxima visita</h3><p>En Seguimiento, prepara un mensaje para una revisita. No se envía a nadie.</p></div></article></div><p class="modal-footnote">Propuesta sin integración con la web, WhatsApp o pagos. Las tarifas proceden de la web; clientes, citas, preferencias y cobros son ficticios.</p><button class="button primary wide" data-action="close-modal">Empezar a probar</button>`,'guide');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='close-modal')$('modal').close();
 if(a==='guide')guide();
 if(a==='new-appointment')appointmentModal(id);
 if(a==='new-pet')newPetModal();
 if(a==='pet')petModal(id);
 if(a==='confirm'){store.transition(id,'confirmed');render();toast('Cita confirmada en la demo. No se ha enviado ningún mensaje.');}
 if(a==='start'){store.transition(id,'active');render();toast('Servicio en curso.');}
 if(a==='finish'){store.transition(id,'done');render();paymentModal(id);}
 if(a==='payment')paymentModal(id);
 if(a==='cancel')modal('Cancelar esta cita de ejemplo',`<p class="form-intro">Se liberará el horario de ${esc(pet(state().appointments.find(x=>x.id===id).petId).name)} en la agenda demo.</p><div class="form-actions"><button class="button secondary" data-action="close-modal">Volver</button><button class="button danger" data-action="confirm-cancel" data-id="${id}">Cancelar cita demo</button></div>`,'cancel');
 if(a==='confirm-cancel'){store.transition(id,'cancelled');$('modal').close();render();toast('Cita de ejemplo cancelada. Horario liberado.');}
 if(a==='message')messageModal(id);
 if(a==='copy-message'){try{await navigator.clipboard.writeText($('followup-message').value);toast('Borrador copiado. No se ha enviado.');}catch{$('followup-message').focus();$('followup-message').select();toast('Selecciona y copia el texto con el menú de tu dispositivo.');}}
 if(a==='mark-prepared'){if(!state().followed.includes(id))state().followed.push(id);$('modal').close();render();toast('Mensaje marcado como preparado. No enviado.');}
 if(a==='previous-day'||a==='next-day'||a==='today'){viewDate=a==='today'?state().today:shift(viewDate,a==='next-day'?1:-1);render();}
 if(a==='reset')modal('¿Volvemos al principio?',`<p class="form-intro">Se eliminarán los cambios de esta sesión y se recuperarán los clientes, citas y cobros ficticios iniciales.</p><div class="form-actions"><button class="button secondary" data-action="close-modal">Seguir probando</button><button class="button primary" data-action="confirm-reset">Restablecer demo</button></div>`,'reset');
 if(a==='confirm-reset'){store.reset();viewDate=state().today;query='';statusFilter='';$('modal').close();render();toast('Demo restablecida. Lista para una nueva presentación.');}
 }catch(err){toast(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='agenda-date'&&e.target.value){viewDate=e.target.value;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(['appointment-pet','appointment-service'].includes(e.target.id))updateEstimate();});
document.addEventListener('input',e=>{if(e.target.id==='pet-search'){const pos=e.target.selectionStart;query=e.target.value;render();$('pet-search').focus();try{$('pet-search').setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',e=>{if(!['appointment-form','new-pet-form','notes-form','payment-form'].includes(e.target.id))return;e.preventDefault();try{
 if(e.target.id==='appointment-form'){const a=store.addAppointment({petId:$('appointment-pet').value,service:$('appointment-service').value,date:$('appointment-date').value,time:$('appointment-time').value,amount:$('appointment-amount').value,channel:$('appointment-channel').value});viewDate=a.date;statusFilter='';$('modal').close();location.hash='agenda';render();toast('Cita de ejemplo creada. Pendiente de confirmar.');}
 if(e.target.id==='new-pet-form'){const p=store.addPet({name:$('new-pet-name').value,owner:$('new-owner').value,breed:$('new-breed').value,weight:$('new-weight').value,notes:$('new-notes').value});query='';location.hash='clientes';render();petModal(p.id);toast('Ficha de ejemplo creada.');}
 if(e.target.id==='notes-form'){store.notes(e.target.dataset.id,$('pet-notes').value);render();toast('Preferencias guardadas durante esta sesión.');}
 if(e.target.id==='payment-form'){store.pay(e.target.dataset.id,$('payment-method').value);$('modal').close();render();toast('Cobro simulado registrado. La caja está actualizada.');}
 }catch(err){if($('form-error')){$('form-error').textContent=err.message;$('form-error').hidden=false;}else toast(err.message);}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});$('main').focus({preventScroll:true});});
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
render();fillIcons();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'get_demo_agenda',title:'Consultar agenda de demostración',description:'Lee la agenda ficticia de la fecha indicada. No modifica ni crea citas reales.',inputSchema:{type:'object',properties:{date:{type:'string',description:'Fecha YYYY-MM-DD'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(input.date))throw Error('Fecha inválida. Usa YYYY-MM-DD.');return {demo:true,date:input.date,appointments:sortedAppointments(input.date).map(a=>({id:a.id,pet:pet(a.petId).name,time:a.time,service:SERVICES[a.service].name,status:STATES[a.status],amount:a.amount}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
